  } 
  int x = rec(a,b,ai+1,bi); 
  int y = rec(a,b,ai,bi+1); 
  return Math.max(x,y); 
} 
public static int dp(String a, String b) 
{ 
   int al = a.length(); 
   int bl = b.length(); 
   int[][] dp = new int[al+ 1][bl + 1]; 
   for(int i = 0;i<al;i++) 
   { 
      for(int j = 0;j<bl;j++) 
      { 
         if(a.charAt(i) == b.charAt(j)) 
         { 
            dp[i+1][j+1] = dp[i][j] + 1; 
         }else{ 
            int x = dp[i][j+1]; 
            int y = dp[i+1][j]; 
            dp[i+1][j+1] = Math.max(x,y); 
         } 
      } 
   } 
   return dp[al][bl]; 
} 
